import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 19 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * earlier Practice Tests.
 */

// ─────────────────────── PRACTICE TEST 19 · R&W M1 (27) ──────────────────────
const T19_RW_M1: SatQuestion[] = [
  { id: "t19rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The cartographer's maps were prized for their ______ detail: every cove, sandbar, and tidal channel appeared exactly where a sailor would expect it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meticulous", "careless", "vague", "decorative"], correct: 0, explanation: "The answer is (A) meticulous. The sentence praises maps in which every cove, sandbar, and tidal channel appears exactly where a sailor expects, so the detail must be extremely careful and precise; \"meticulous\" means showing great attention to detail, which matches. (B) careless means done without care — the opposite of detail placed exactly. (C) vague means unclear or imprecise, contradicting the exact placement described. (D) decorative refers to ornamentation for appearance, but the praise concerns accuracy, not adornment." },
  { id: "t19rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of scientists ______ scheduled to release its findings at the conference next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "The answer is (A) is. This tests subject-verb agreement. The grammatical subject is the singular collective noun \"committee\"; the plural \"scientists\" sits inside the prepositional phrase \"of scientists\" and never controls the verb. A singular subject takes the singular verb \"is.\" (B) are and (D) were are plural and disagree with \"committee.\" (C) have been is also plural and additionally shifts to a perfect tense the sentence does not need. The trap is matching the verb to the nearby plural \"scientists.\"" },
  { id: "t19rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Coral polyps secrete calcium carbonate to build the reef around themselves; over centuries, the accumulated skeletons of countless generations form structures large enough to be seen from space.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Reefs are built gradually from the calcium carbonate skeletons of many generations of coral.", "Coral polyps avoid producing calcium carbonate.", "Reefs form within a single year.", "Coral skeletons dissolve before any reef can form."], correct: 0, explanation: "The answer is (A). The text states that polyps secrete calcium carbonate and that, over centuries, the accumulated skeletons of countless generations form structures large enough to be seen from space; (A) captures exactly this gradual, multi-generational building of the reef. (B) is contradicted by \"secrete calcium carbonate to build the reef\" — they do produce it, not avoid it. (C) contradicts \"over centuries,\" which signals a slow process, not a single year. (D) contradicts the accumulation described — the skeletons build up, they do not dissolve before a reef forms." },
  { id: "t19rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail was washed out by the spring floods. ______, the rangers closed it until repairs could be completed.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "In contrast"], correct: 1, explanation: "The answer is (B) Consequently. The first sentence gives a cause (the trail was washed out by floods) and the second gives its effect (the rangers closed it), so a cause-and-effect transition is needed; \"Consequently\" means \"as a result\" and fits. (A) Nevertheless, (C) However, and (D) In contrast all signal a contrast or concession, but there is no opposition here — closing a damaged trail follows naturally from the damage. The trap is reaching for a contrast word out of habit." },
  { id: "t19rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The expedition packed three essentials ______ a satellite phone, a first-aid kit, and extra fuel.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["essentials, ", "essentials: ", "essentials; ", "essentials "], correct: 1, explanation: "The answer is (B) essentials: — a colon. The rule: a colon follows a complete independent clause (\"The expedition packed three essentials\") and introduces an explanation or list of what that clause refers to. Here the list of three items defines the \"three essentials,\" so a colon is correct. (A) the comma is too weak to announce a defining list this way. (C) the semicolon is wrong because it must join two independent clauses, and the list is not a clause. (D) no punctuation runs the introduction straight into the list. The trap is treating any pause as comma-worthy." },
  { id: "t19rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her lab notebook was unusually ______, with each measurement dated, labeled, and cross-referenced to the raw data.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["systematic", "haphazard", "brief", "illegible"], correct: 0, explanation: "The answer is (A) systematic. The detail that each measurement is dated, labeled, and cross-referenced describes a careful, methodical order, and \"systematic\" means done according to an organized method or plan. (B) haphazard means lacking order or method — the opposite of the orderly records shown. (C) brief means short, but the entries are described as detailed and thorough, not short. (D) illegible means unreadable, which the careful labeling contradicts. The trap is choosing a word about the notebook's appearance rather than its organization." },
  { id: "t19rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The fellowship is awarded only to artists who have completed at least one published book and who reside within the state; applicants who fail either requirement are not considered.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["An out-of-state author with a published book would not qualify.", "Every applicant automatically qualifies.", "The fellowship is open to unpublished writers anywhere.", "Residency alone guarantees the award."], correct: 0, explanation: "The answer is (A). The text states the fellowship goes only to artists who have BOTH a published book AND in-state residency, and that failing either requirement means no consideration. An out-of-state author with a published book meets the publication rule but fails residency, so they would not qualify — (A) is directly supported. (B) is wrong because the strict \"only\" requirements mean not every applicant qualifies. (C) contradicts the publication requirement (\"at least one published book\"). (D) contradicts the dual requirement — residency alone is not enough without a published book." },
  { id: "t19rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum digitized its entire photo archive. ______, it launched a public website where anyone could browse the collection.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Otherwise", "Instead"], correct: 1, explanation: "The answer is (B) In addition. The museum first digitized its archive and then launched a public website; the second action is a further, complementary step in the same effort, so an additive transition is needed, and \"In addition\" means \"furthermore.\" (A) However signals contrast, but the two actions agree rather than oppose. (D) Instead signals replacement, yet the website supplements the digitizing rather than replacing it. (C) Otherwise implies an alternative consequence (\"if not, then…\"), which does not fit. The trap is reading sequence as contrast." },
  { id: "t19rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the chef's tasting menu ______, noting that each course built on the last toward a single, coherent theme.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "disjointed", "bland", "wasteful"], correct: 0, explanation: "The answer is (A) cohesive. The clarifying detail — each course building on the last toward a single, coherent theme — describes parts that fit together as a unified whole, which is exactly what \"cohesive\" means. (B) disjointed means disconnected or lacking unity, the opposite of building toward one theme. (C) bland describes a lack of flavor, not a lack of unity, so it misses the point about structure. (D) wasteful concerns excess or inefficiency, which the sentence never raises. The trap is choosing a flavor word for a sentence about coherence." },
  { id: "t19rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Desert kangaroo rats can survive without ever drinking water, instead producing the moisture they need by metabolizing the dry seeds they eat.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Kangaroo rats meet their water needs by metabolizing the seeds they eat.", "Kangaroo rats drink large amounts of water daily.", "Kangaroo rats cannot survive in deserts.", "Kangaroo rats eat only moist foods."], correct: 0, explanation: "The answer is (A). The text says kangaroo rats survive without ever drinking water and instead produce the moisture they need by metabolizing the dry seeds they eat — (A) restates this central point. (B) contradicts \"without ever drinking water.\" (C) contradicts the opening claim that they \"can survive\" in the desert. (D) contradicts \"dry seeds,\" since the seeds are explicitly dry rather than moist. The trap is picking a choice that sounds reasonable about desert animals but conflicts with a stated detail." },
  { id: "t19rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither of the two proposals ______ ready for a vote at today's meeting.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The answer is (A) is. This tests subject-verb agreement with an indefinite pronoun. \"Neither\" is grammatically singular and takes a singular verb; the plural \"proposals\" sits inside the phrase \"of the two proposals\" and never controls the verb. So the singular \"is\" is correct. (B) are and (C) were are plural and disagree with the singular \"Neither.\" (D) have been is also plural and adds an unneeded perfect tense. The trap is letting the nearby plural \"proposals\" pull the verb into the plural." },
  { id: "t19rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first edition of the dictionary sold poorly. ______, it later became a collector's item prized by linguists.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "The answer is (A) Still. The first sentence reports a negative (the dictionary sold poorly) and the second an unexpected positive (it later became a prized collector's item), so a contrast transition is needed; \"Still\" works here like \"nevertheless.\" (C) Therefore implies the prestige was caused by the poor sales, which is illogical. (B) For instance introduces an example, but the second sentence is not an example of the first. (D) In short signals a summary, yet a new and contrasting fact is being added, not summarized." },
  { id: "t19rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study reported recall accuracy of 88% among participants who slept eight hours, 74% among those who slept six hours, and 59% among those who slept four hours.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Recall accuracy decreased as sleep duration decreased.", "Recall accuracy was highest among those who slept four hours.", "Sleep had no effect on recall accuracy.", "All three groups recalled equally well."], correct: 0, explanation: "The answer is (A). The data show recall accuracy of 88% at eight hours of sleep, 74% at six hours, and 59% at four hours: as sleep duration drops, accuracy drops too, exactly what (A) states. (B) is wrong because the four-hour group had the lowest accuracy (59%), not the highest. (C) is contradicted by the clear differences across the three figures — sleep plainly mattered. (D) is wrong because the three groups scored quite differently (88 vs. 74 vs. 59). The trap is choosing a flat \"no effect\" reading despite an obvious downward trend." },
  { id: "t19rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The archive contains a manuscript ______ had been thought lost since the eighteenth century.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "The answer is (A) that. The blank needs a relative pronoun to attach the clause \"had been thought lost…\" to the noun \"manuscript,\" and \"that\" is the standard relative pronoun for a thing. (B) what cannot introduce a relative clause modifying a stated noun — \"what\" is used without an antecedent. (C) where introduces a clause about a place, but a manuscript is a thing, not a location. (D) and it would start a new independent clause, producing a comma-splice-style error rather than modifying \"manuscript.\" The trap is hearing \"and it\" as smooth speech while it breaks the grammar." },
  { id: "t19rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Stepping off the train, ______ the unfamiliar skyline left the traveler momentarily disoriented.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["stepping off the train, the unfamiliar skyline left the traveler disoriented", "the traveler stepped off the train and felt disoriented by the unfamiliar skyline", "the unfamiliar skyline, stepping off the train, disoriented the traveler", "disoriented, the unfamiliar skyline confused the traveler off the train"], correct: 1, explanation: "The answer is (B). This tests the dangling/misplaced modifier rule: an introductory participial phrase like \"Stepping off the train\" must be immediately followed by the noun that performs the action. Only a person can step off a train, so \"the traveler\" must come right after the comma, which (B) does. (A) places \"the unfamiliar skyline\" after the phrase, illogically making the skyline step off the train. (C) buries \"stepping off the train\" mid-sentence so it still attaches to the skyline. (D) is incoherent and again makes the skyline do the stepping. The trap is accepting (A) because it merely repeats the original wording." },
  { id: "t19rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist argues that remote work, though it lengthens some projects, boosts overall productivity because employees lose less time to commuting and interruptions.", prompt: "Which finding, if true, would most strengthen the economist's claim?", type: "mcq", choices: ["Firms that adopted remote work completed more total output per worker than comparable in-office firms.", "Remote employees spend more time in scheduled meetings.", "Most workers say they prefer working from home.", "Commutes are shorter on weekends than on weekdays."], correct: 0, explanation: "The answer is (A). The economist claims remote work boosts overall productivity because workers lose less time to commuting and interruptions. A finding that remote firms produced more total output per worker than comparable in-office firms is direct evidence of higher productivity, so it strengthens the claim. (B) more time in meetings is a form of interruption that would weaken, not strengthen, the claim. (C) workers preferring home is about satisfaction, not output, so it is irrelevant to productivity. (D) weekend commute times have no bearing on workday productivity. The trap is choosing a pleasant-sounding fact (preference) that does not measure the claim." },
  { id: "t19rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with her camera operators, ______ filming the final scene at dawn tomorrow.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The answer is (A) is. This tests subject-verb agreement with an intervening phrase. The subject is the singular \"director\"; phrases beginning with \"together with\" (like \"as well as\" or \"along with\") are parenthetical and do NOT make the subject plural. So a singular verb is required, and \"is\" fits the present, near-future action (\"filming … tomorrow\"). (B) are and (C) were are plural and disagree with \"director.\" (D) have been is plural and adds an unneeded perfect tense. The trap is letting the plural \"operators\" inside the \"together with\" phrase control the verb." },
  { id: "t19rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to underscore that two independent teams reached the same surprising result. ______, both groups measured the comet's tail at nearly the same length.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "The answer is (B) Remarkably. The researcher's goal is to stress that two independent teams reached the same surprising result, so the transition should flag how striking the agreement is; \"Remarkably\" does exactly that. (A) By contrast and (C) However signal opposition, wrongly implying the teams disagreed when they actually matched. (D) Otherwise implies an alternative consequence (\"if not, then…\"), which does not fit a sentence emphasizing agreement. The trap is choosing a contrast word even though the point is shared, surprising agreement." },
  { id: "t19rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The novel's ending is intentionally ______: readers close the book unsure whether the protagonist has triumphed or merely deceived herself.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "explicit", "predictable", "cheerful"], correct: 0, explanation: "The answer is (A) ambiguous. The clarifying clause — readers close the book unsure whether the protagonist triumphed or merely deceived herself — describes an ending open to more than one interpretation, which is what \"ambiguous\" means. (B) explicit means clearly and fully stated, the opposite of leaving readers unsure. (C) predictable means the outcome is easy to foresee, again contradicting the described uncertainty. (D) cheerful describes mood, not the interpretive openness the sentence emphasizes. The trap is picking a tone word instead of one about clarity of meaning." },
  { id: "t19rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate applies only to vehicles purchased new after January and registered to a household within the city limits; used or out-of-city purchases do not qualify.", prompt: "Which vehicle clearly qualifies for the rebate?", type: "mcq", choices: ["A new car bought in March and registered to a household inside the city.", "A used car bought in March within the city.", "A new car bought in March and registered outside the city.", "A car bought before January."], correct: 0, explanation: "The answer is (A). The rebate requires three things: the vehicle must be new, purchased after January, AND registered to a household inside the city. (A) — a new car bought in March and registered inside the city — satisfies all three. (B) fails the \"new\" requirement because it is a used car. (C) fails the in-city registration requirement because it is registered outside the city. (D) fails the timing requirement because it was bought before January. The trap is matching only one or two conditions and overlooking the one that disqualifies the choice." },
  { id: "t19rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the lighthouse lens ______ they repainted the weathered iron railing.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["lens, and then", "lens and, then", "lens then", "lens, then"], correct: 0, explanation: "The answer is (A) lens, and then. \"The crew repaired the lighthouse lens\" and \"they repainted the weathered iron railing\" are both independent clauses; the rule is that two independent clauses are joined by a comma plus a coordinating conjunction (here \"and\"). (A) correctly places the comma before \"and then.\" (B) misplaces the comma after \"and,\" splitting the conjunction from its clause. (C) lens then omits the comma and conjunction, creating a run-on. (D) lens, then is a comma splice — \"then\" is an adverb, not a coordinating conjunction, so a comma alone cannot join the clauses. The trap is treating \"then\" as if it could join clauses like \"and.\"" },
  { id: "t19rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although he was famous for his ______ negotiating style, the executive could be remarkably patient when mentoring younger colleagues.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["aggressive", "gentle", "timid", "indifferent"], correct: 0, explanation: "The answer is (A) aggressive. The word \"Although\" sets up a contrast with \"remarkably patient when mentoring,\" so the blank must describe a negotiating style that is the opposite of patient and gentle; \"aggressive\" fits. (B) gentle and (C) timid both align with patience rather than contrasting with it, so they break the \"Although\" contrast. (D) indifferent means uninterested or uncaring, which does not describe a forceful negotiating style and does not contrast meaningfully with patience. The trap is ignoring the contrast cue and picking a word that matches \"patient\" instead of opposing it." },
  { id: "t19rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A geographer notes that coastal cities with deep natural harbors grew into trade hubs faster than those with shallow ports, crediting the ease of docking large ships.", prompt: "Which choice best describes the geographer's explanation?", type: "mcq", choices: ["Deep harbors let large ships dock easily, accelerating a city's growth as a trade hub.", "Shallow ports attracted more shipping than deep harbors.", "Harbor depth had no effect on trade.", "Large ships avoided deep harbors."], correct: 0, explanation: "The answer is (A). The geographer observes that cities with deep natural harbors became trade hubs faster than those with shallow ports, and credits the ease of docking large ships — (A) states this cause (deep harbors, easy docking) and effect (accelerated growth). (B) reverses the relationship by claiming shallow ports drew more shipping. (C) denies any effect, contradicting the geographer's explicit explanation. (D) wrongly claims large ships avoided deep harbors, when deep harbors are exactly where large ships dock easily. The trap is choosing a reversed or negated version of the stated relationship." },
  { id: "t19rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The council delayed the vote ______ it still lacked the engineering report it had requested.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["vote because", "vote, because", "vote; because", "vote: because"], correct: 0, explanation: "The answer is (A) vote because. The rule: when a subordinate clause beginning with \"because\" follows the main clause and is essential to its meaning (here explaining why the vote was delayed), no comma is used before it. (B) the comma is unnecessary and wrongly separates the cause from the clause it modifies. (C) a semicolon must join two independent clauses, but \"because it still lacked…\" is a dependent clause, not independent. (D) a colon must follow a complete clause and introduce an explanation list or summary, which a \"because\" clause is not. The trap is inserting a pause-comma before \"because\" when none is needed." },
  { id: "t19rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The new irrigation system cut the farm's water use by a third. ______, it lowered the farm's annual costs substantially.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The answer is (A) As a result. The first sentence gives a cause (the system cut water use by a third) and the second its effect (lower annual costs), so a cause-and-effect transition is needed, and \"As a result\" means \"consequently.\" (B) Nevertheless and (D) On the other hand signal contrast, but the two sentences agree rather than oppose. (C) For example introduces an illustration, yet the cost savings are a consequence, not an example, of reduced water use. The trap is reading a logical result as a mere example or a contrast." },
  { id: "t19rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The instructor gave ______ feedback, pointing to the exact lines a student could revise rather than offering vague encouragement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "abstract", "evasive", "irrelevant"], correct: 0, explanation: "The answer is (A) specific. The sentence contrasts the instructor's feedback with \"vague encouragement\" and says it pointed to the exact lines a student could revise, so the feedback must be precise and detailed; \"specific\" fits. (B) abstract means general or theoretical, aligning with the vagueness the sentence explicitly rejects. (C) evasive means avoiding directness, again the opposite of pointing to exact lines. (D) irrelevant means unrelated, but nothing suggests the feedback was off-topic. The trap is choosing a word that matches \"vague\" instead of contrasting with it." },
  { id: "t19rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study found that reintroducing beavers to a degraded watershed slowed runoff, which raised the water table, which in turn allowed drought-stressed meadows to green again.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Returning beavers set off a chain of effects that helped degraded meadows recover.", "Beavers directly planted the meadow grasses.", "The water table fell after the beavers returned.", "Meadows withered once the beavers arrived."], correct: 0, explanation: "The answer is (A). The text traces a chain: reintroducing beavers slowed runoff, which raised the water table, which in turn let drought-stressed meadows green again. (A) captures this sequence of effects leading to recovery. (B) misstates the mechanism — the beavers did not plant grasses; recovery came indirectly through the water table. (C) contradicts the text, which says the water table rose, not fell. (D) contradicts \"green again,\" since the meadows recovered rather than withered. The trap is choosing the direct-action option (B) when the passage describes an indirect, multi-step effect." },
];

// ─────────────────────── PRACTICE TEST 19 · R&W M2 easy (27) ─────────────────
const T19_RW_M2E: SatQuestion[] = [
  { id: "t19rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was too ______ to carry, so we took some books out of it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "empty", "green", "quiet"], correct: 0, explanation: "The answer is (A) heavy. The sentence says they took books out of the backpack, and the most logical reason to remove weight is that it was too \"heavy\" to carry. (B) empty makes no sense — an empty backpack would have no books to remove. (C) green is a color and gives no reason to take books out. (D) quiet describes sound, which has nothing to do with how hard a backpack is to carry. The trap is picking a word that does not explain the action of removing books." },
  { id: "t19rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The two puppies ______ playing in the yard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) are. This tests subject-verb agreement. The subject \"two puppies\" is plural, so it needs the plural verb \"are\" (\"are playing\"). (A) is and (C) was are singular and disagree with a plural subject. (D) am is the first-person singular form, used only with \"I,\" so it cannot go with \"puppies.\" The trap is not matching the verb to the plural subject." },
  { id: "t19rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bats are not blind; many use echoes from their own calls to find insects in the dark.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bats use echoes to locate insects at night.", "Bats cannot find food in the dark.", "Bats are completely blind.", "Bats hunt only during the day."], correct: 0, explanation: "The answer is (A). The text says bats are not blind and that many use echoes from their own calls to find insects in the dark, so (A) restates the main point. (B) contradicts the text, which shows bats can find food in the dark using echoes. (C) directly contradicts \"Bats are not blind.\" (D) contradicts \"in the dark,\" since the text describes nighttime hunting, not daytime. The trap is choosing an option that reverses a stated detail." },
  { id: "t19rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "It began to rain hard. ______, we moved the picnic inside.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The answer is (B) So. The first sentence is a cause (it began to rain hard) and the second its effect (they moved the picnic inside), so a cause-and-effect word is needed, and \"So\" means \"therefore.\" (A) For example introduces an illustration, but moving inside is a consequence, not an example. (C) However signals contrast, yet the two actions agree. (D) Meanwhile signals two things happening at the same time, which misses the cause-and-effect link. The trap is reading a clear consequence as a contrast." },
  { id: "t19rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at our grandmother's house.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "The answer is (C) ate. The time marker \"Last night\" places the action in the past, so the past-tense verb \"ate\" is required. (A) eat is present tense and does not match the past. (B) eats is the present third-person singular form, also wrong for the past and for the subject \"we.\" (D) eating is a participle that cannot stand alone as the verb without a helping verb. The trap is overlooking the past-time signal \"Last night.\"" },
  { id: "t19rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puzzle was ______, so it took us all afternoon to finish.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["difficult", "simple", "tiny", "warm"], correct: 0, explanation: "The answer is (A) difficult. The clue \"it took us all afternoon to finish\" shows the puzzle was hard, and \"difficult\" means hard to do. (B) simple means easy, which would not take all afternoon — the opposite of the clue. (C) tiny describes size, not difficulty, and does not explain the long time. (D) warm describes temperature and is unrelated to a puzzle's difficulty. The trap is choosing a word that does not match the \"all afternoon\" time clue." },
  { id: "t19rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, reduces traffic, and gives students daily exercise.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is harmful.", "Walking to school only saves money.", "Driving to school is always better."], correct: 0, explanation: "The answer is (A). The text lists three positives of walking to school — saving money, reducing traffic, and providing daily exercise — so the main idea is that it has several benefits, as (A) says. (B) contradicts the positive list by calling it harmful. (C) names only one benefit (saving money) and ignores the other two. (D) makes a comparison to driving that the text never makes. The trap is picking a choice that captures just one detail (C) instead of the full set." },
  { id: "t19rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She wore ______ orange scarf to the parade.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is (B) an. The rule for the indefinite article: use \"an\" before a word that begins with a vowel sound. \"Orange\" begins with the vowel sound /o/, so \"an orange\" is correct. (A) a is used before consonant sounds, so it is wrong before \"orange.\" (C) the only and (D) some are not indefinite articles and change the meaning (specifying or quantifying) rather than simply introducing a single scarf. The trap is defaulting to \"a\" without listening for the vowel sound." },
  { id: "t19rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The lake was so ______ that we could see the pebbles at the bottom.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "muddy", "loud", "frozen"], correct: 0, explanation: "The answer is (A) clear. The clue \"we could see the pebbles at the bottom\" means the water let light through, and \"clear\" means transparent. (B) muddy water is cloudy and would hide the pebbles, the opposite of the clue. (D) frozen water (ice) would also obscure the bottom and does not fit \"see the pebbles.\" (C) loud describes sound, not how see-through the water is. The trap is choosing a water word that contradicts being able to see the bottom." },
  { id: "t19rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My cousin and I ______ planning a trip to the mountains.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) are. This tests subject-verb agreement with a compound subject. \"My cousin and I\" joins two people with \"and,\" making the subject plural, so it takes the plural verb \"are.\" (A) is and (C) was are singular and disagree with the plural subject. (D) am is first-person singular, used only with \"I\" alone, not with \"my cousin and I.\" The trap is treating the subject as singular because it ends in \"I.\"" },
  { id: "t19rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Earthworms loosen soil as they tunnel, which lets air and water reach plant roots more easily.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Earthworms help soil by loosening it as they tunnel.", "Earthworms pack soil tightly.", "Earthworms keep water away from roots.", "Earthworms harm plant roots."], correct: 0, explanation: "The answer is (A). The text says earthworms loosen soil as they tunnel, letting air and water reach plant roots more easily, so (A) restates this benefit. (B) contradicts \"loosen soil,\" since loosening is the opposite of packing it tightly. (C) contradicts the point that tunneling lets water reach roots. (D) contradicts the helpful effect, since reaching roots aids plants rather than harming them. The trap is choosing an option that reverses the stated benefit." },
  { id: "t19rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, the whole street went dark.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "The answer is (B) As a result. The first sentence is a cause (the power went out) and the second its effect (the street went dark), so a cause-and-effect transition is needed; \"As a result\" means \"consequently.\" (A) However and (D) Instead signal contrast or replacement, but the two sentences agree. (C) For example introduces an illustration, yet the dark street is a consequence of the outage, not an example of it. The trap is reading a direct result as a contrast." },
  { id: "t19rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the choir ______ a new song for the spring concert.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["learn", "learns", "learned", "learning"], correct: 2, explanation: "The answer is (C) learned. The time marker \"Yesterday\" places the action in the past, so the past-tense verb \"learned\" is required. (A) learn is present tense and does not match the past. (B) learns is the present third-person singular form, wrong for the past. (D) learning is a participle that needs a helping verb and cannot stand alone as the main verb. The trap is missing the past-time signal \"Yesterday.\"" },
  { id: "t19rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After studying for hours, the student felt ______ and went straight to bed.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "excited", "hungry", "curious"], correct: 0, explanation: "The answer is (A) tired. The clues \"After studying for hours\" and \"went straight to bed\" point to exhaustion, and \"tired\" means in need of rest or sleep. (B) excited would more likely keep the student up, not send them to bed. (C) hungry would lead to eating, not sleeping. (D) curious describes wanting to learn more, which does not explain going to bed. The trap is picking a feeling that does not match the action of going straight to sleep." },
  { id: "t19rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from noon to eight in the evening on weekdays but stays closed on Mondays.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["You cannot swim at the pool on Mondays.", "The pool opens at dawn.", "The pool is open every day.", "The pool closes at noon."], correct: 0, explanation: "The answer is (A). The text says the pool stays closed on Mondays, so you cannot swim there on a Monday — (A) is directly supported. (B) contradicts the stated opening time of noon, not dawn. (C) contradicts \"closed on Mondays,\" so it is not open every day. (D) misreads the hours: noon is when the pool opens, not closes. The trap is confusing the opening time (noon) with a closing time." },
  { id: "t19rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat curled up in ______ favorite spot by the window.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The answer is (A) its. The blank needs a singular possessive to show the spot belongs to the cat, and \"its\" is the possessive of \"it\" (no apostrophe). (B) it's is a contraction of \"it is\" — \"it is favorite spot\" is ungrammatical. (C) their is plural and does not agree with the single cat. (D) they're is a contraction of \"they are,\" both plural and a verb phrase, not a possessive. The trap is confusing the possessive \"its\" with the contraction \"it's.\"" },
  { id: "t19rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some animals sleep through the winter. ______, bears hibernate for months in their dens.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is (A) For example. The first sentence makes a general claim (some animals sleep through winter) and the second gives a specific instance (bears hibernate for months), so an example transition is needed; \"For example\" fits. (B) However and (C) Instead signal contrast or replacement, but the bear case supports the general claim rather than opposing it. (D) Otherwise implies an alternative consequence, which does not match an illustration. The trap is reading a supporting example as a contrast." },
  { id: "t19rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The soup needed more flavor, so the cook added a ______ of salt.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["pinch", "gallon", "color", "shadow"], correct: 0, explanation: "The answer is (A) pinch. To add a little flavor a cook adds a small amount of salt, and a \"pinch\" is the standard word for a tiny quantity held between finger and thumb. (B) gallon is a huge liquid measure — far too much salt and the wrong kind of unit. (C) color and (D) shadow are not amounts of anything and cannot be added to soup. The trap is choosing a noun that is not a measure of salt." },
  { id: "t19rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The shelves ______ filled with books of every size.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) are. This tests subject-verb agreement. The subject \"shelves\" is plural (the plural of \"shelf\"), so it takes the plural verb \"are.\" (A) is and (C) was are singular and disagree with the plural subject. (D) am is first-person singular, used only with \"I,\" so it cannot go with \"shelves.\" The trap is missing that \"shelves\" is plural." },
  { id: "t19rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Salt was once so valuable that it was used as money in some ancient societies.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Salt was highly valued and even used as money in the past.", "Salt has never had any value.", "Salt cannot be traded.", "Salt was useless to ancient people."], correct: 0, explanation: "The answer is (A). The text says salt was once so valuable that some ancient societies used it as money, so (A) restates this high value. (B) contradicts \"so valuable,\" since the text shows salt did have value. (C) contradicts using salt as money, which is a form of trade. (D) contradicts \"valuable,\" since something useless would not serve as currency. The trap is choosing an option that denies the value the text clearly asserts." },
  { id: "t19rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to hike the long trail. ______, a sudden storm forced us to turn back.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "The answer is (A) However. The first sentence states a plan (to hike the long trail) and the second states something that blocked it (a sudden storm forced them back), so a contrast transition is needed; \"However\" signals that reversal. (B) Therefore implies the storm was a result of the plan, which is illogical. (C) Similarly signals likeness, but the storm opposes the plan rather than matching it. (D) For example introduces an illustration, which the storm is not. The trap is overlooking the opposition between the plan and what actually happened." },
  { id: "t19rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month our class ______ to visit the science center.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The answer is (B) plans. This tests subject-verb agreement and tense. \"Class\" is a singular collective noun, so it takes the singular present verb \"plans,\" and \"next month\" works with the present tense used for a scheduled future event. (A) plan is the plural/base form and does not agree with the singular \"class.\" (C) planned is past tense, which clashes with the future \"next month.\" (D) planning is a participle that needs a helping verb and cannot stand alone. The trap is treating \"class\" as plural or matching the verb to a future word with the wrong tense." },
  { id: "t19rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new tablet is very ______; it can run all day on a single charge.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["efficient", "wasteful", "broken", "noisy"], correct: 0, explanation: "The answer is (A) efficient. The clue \"it can run all day on a single charge\" means the tablet uses little power for the work it does, and \"efficient\" means achieving much with little waste. (B) wasteful means using more than needed, the opposite of long battery life. (C) broken would mean it does not work at all, contradicting running all day. (D) noisy describes sound and has nothing to do with battery use. The trap is choosing a word that contradicts the long-lasting charge." },
  { id: "t19rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Planting trees in a city can provide shade, clean the air, and give birds a place to nest.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Planting city trees offers several benefits.", "City trees serve no purpose.", "Trees harm city air.", "Trees only provide shade."], correct: 0, explanation: "The answer is (A). The text lists three positives of planting city trees — providing shade, cleaning the air, and giving birds a place to nest — so the main idea is that doing so offers several benefits, as (A) says. (B) contradicts the list by claiming trees serve no purpose. (C) contradicts \"clean the air,\" since trees help rather than harm city air. (D) names only one benefit (shade) and ignores the other two. The trap is choosing an option that captures just one detail or reverses the positive point." },
  { id: "t19rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He ordered ______ apple from the snack cart.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is (B) an. The rule for the indefinite article: use \"an\" before a word beginning with a vowel sound. \"Apple\" begins with the vowel sound /a/, so \"an apple\" is correct. (A) a is used before consonant sounds and is wrong before \"apple.\" (C) the only and (D) some are not indefinite articles and change the meaning rather than introducing a single apple. The trap is defaulting to \"a\" without noticing the vowel sound." },
  { id: "t19rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The directions were clear and short. ______, the recipe used only five ingredients.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is (A) In addition. The first sentence praises one easy feature (clear, short directions) and the second adds another (only five ingredients), so an additive transition is needed; \"In addition\" means \"furthermore.\" (B) However and (C) Instead signal contrast or replacement, but the two features agree. (D) Otherwise implies an alternative consequence, which does not fit two stacked positives. The trap is reading a second point as if it opposed the first." },
  { id: "t19rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the rabbit disappear.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "The answer is (A) amazed. A magician making a rabbit disappear is a surprising feat, so the audience would be filled with wonder, and \"amazed\" means greatly surprised or astonished. (B) bored and (C) sleepy suggest a lack of interest, the opposite of reacting to a surprising trick. (D) angry does not fit a successful, entertaining performance. The trap is choosing an emotion that does not match the wonder of a magic trick." },
];

// ─────────────────────── PRACTICE TEST 19 · R&W M2 hard (27) ─────────────────
const T19_RW_M2H: SatQuestion[] = [
  { id: "t19rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The official's statement was so ______ that supporters and critics alike claimed it endorsed their position.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["equivocal", "candid", "blunt", "decisive"], correct: 0, explanation: "The answer is (A) equivocal. The clue is that both supporters and critics claimed the statement endorsed their position, which is only possible if the statement was deliberately unclear or open to opposite readings; \"equivocal\" means ambiguous or able to be interpreted two ways. (B) candid means honest and frank, implying clarity, not double meaning. (C) blunt means direct and plainspoken, again the opposite of two-sided. (D) decisive means clear and conclusive, which would settle the matter rather than let both sides claim it. The trap is choosing a 'clear-speech' word when the sentence requires deliberate vagueness." },
  { id: "t19rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The lecture spends most of its time recounting a single failed expedition before, in its closing minutes, distilling from that story a general lesson about risk.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from a detailed example to a broader generalization.", "It opens with a thesis it never supports.", "It lists unrelated definitions.", "It repeats one statistic throughout."], correct: 0, explanation: "The answer is (A). The lecture spends most of its time on one detailed case (a single failed expedition) and then, in its closing minutes, draws a general lesson about risk from it — a move from a specific example to a broad generalization, which is (A). (B) is wrong because the lecture builds toward its general point rather than opening with an unsupported thesis. (C) is wrong because it recounts a connected story, not a list of unrelated definitions. (D) is wrong because no single statistic is repeated throughout. The trap is mistaking the order of specific-then-general for a thesis-first structure." },
  { id: "t19rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A reservoir was at 95% capacity in spring, 90% by midsummer, and 62% by early autumn.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The reservoir's level dropped more sharply in late summer than in early summer.", "The reservoir filled steadily through the year.", "The level stayed constant all year.", "The reservoir was empty by midsummer."], correct: 0, explanation: "The answer is (A). The reservoir fell from 95% to 90% in early summer (a 5-point drop) but from 90% to 62% by early autumn (a 28-point drop), so the decline was much sharper in late summer, as (A) says. (B) contradicts the falling figures — the level dropped, it did not fill. (C) contradicts the changing numbers, since the level did not stay constant. (D) contradicts the 90% midsummer reading, which is far from empty. The trap is comparing only start and end points and missing that the two drops were very different in size." },
  { id: "t19rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The plan would shorten the harvest season dramatically. ______, it would require machinery too costly for small farms to afford.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "The answer is (B) However. The first sentence gives an advantage (the plan would dramatically shorten the harvest season) and the second a drawback (it needs machinery too costly for small farms), so a contrast transition is needed; \"However\" signals that opposition. (A) Therefore and (D) Accordingly signal a consequence, but the drawback is not caused by the benefit. (C) Likewise signals similarity, yet the two sentences pull in opposite directions. The trap is treating a pro-then-con pairing as cause-and-effect." },
  { id: "t19rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The program teaches interns to draft reports, to lead meetings, and ______ data clearly.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel structure with \"to draft\" and \"to lead\" requires the infinitive \"to present.\" The gerund and bare or past forms break the parallelism." },
  { id: "t19rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir refuses to ______ its author's youth, recounting his cruelties as frankly as his kindnesses.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["romanticize", "condemn", "record", "recall"], correct: 0, explanation: "Recounting cruelties as frankly as kindnesses means the memoir refuses to \"romanticize\" the author's youth. \"Condemn\" is the opposite extreme, and \"record\" and \"recall\" describe neutral acts the memoir clearly does perform." },
  { id: "t19rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats the famine as a purely natural disaster, the revised history casts it as the predictable outcome of misguided policy.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast a natural-disaster account of a famine with a policy-driven one.", "To prove the famine had no human causes.", "To summarize only the traditional account.", "To deny that the famine occurred."], correct: 0, explanation: "The \"Where … the … the revised …\" construction contrasts two explanations of the famine (choice A). B and D contradict the policy-driven view, and C ignores the second account." },
  { id: "t19rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The afternoon class mastered the material quickly ______ the morning class needed several extra sessions.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["quickly, the", "quickly; the", "quickly the", "quickly: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone creates a splice, no punctuation creates a run-on, and a colon requires the second part to explain the first." },
  { id: "t19rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the report is so guarded that its key recommendation must be inferred from a single buried footnote.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["forthright", "evasive", "guarded", "cautious"], correct: 0, explanation: "\"Far from\" signals the opposite of what follows; a report so guarded that its point is buried is the opposite of \"forthright\" (frank and open). \"Evasive,\" \"guarded,\" and \"cautious\" all match the guardedness rather than contrast with it." },
  { id: "t19rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Officials claimed the new bypass had eliminated downtown congestion. Yet in the months after it opened, average rush-hour speeds downtown actually fell.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It offers evidence that complicates the officials' claim.", "It restates the officials' claim word for word.", "It confirms congestion was eliminated.", "It proposes building a second bypass."], correct: 0, explanation: "Slower rush-hour speeds complicate the claim that congestion was eliminated (choice A). B and C misread the contradiction signaled by \"Yet,\" and D introduces a proposal the text does not make." },
  { id: "t19rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The grant rewarded three traits ______ originality, feasibility, and clear public benefit.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["traits,", "traits:", "traits;", "traits"], correct: 1, explanation: "A colon correctly introduces the list specifying the \"three traits.\" A comma is too weak, a semicolon must separate independent clauses, and no punctuation leaves the list unmarked." },
  { id: "t19rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine produced strong antibody levels in early trials. ______, it offered little protection against the newest variant.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "A strong early result followed by a notable shortfall is a concession, best signaled by \"Nonetheless.\" \"Indeed,\" \"Therefore,\" and \"Likewise\" imply agreement or consequence." },
  { id: "t19rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, soil treated with the additive retained 40% more moisture than untreated soil, but it also supported 15% fewer earthworms.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The additive raised moisture retention but lowered earthworm counts.", "The additive raised both moisture and earthworm counts.", "The additive had no measurable effect.", "Untreated soil retained more moisture."], correct: 0, explanation: "Treated soil held more moisture (+40%) but had fewer earthworms (−15%), exactly choice A. B and D contradict the reported figures, and C ignores both measured changes." },
  { id: "t19rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The statue that stands in the courtyard ______ to a sculptor whose later commissions made her famous.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "The singular subject \"statue\" (not the plural \"commissions\" inside the modifier) takes the singular verb \"belongs.\" \"Belong\" is plural, and \"belonging\" and \"to belong\" are nonfinite." },
  { id: "t19rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor was known for her ______ — for cutting any sentence that did not earn its place on the page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["rigor", "leniency", "indecision", "nostalgia"], correct: 0, explanation: "Cutting every sentence that fails to earn its place shows demanding strictness, which is \"rigor.\" \"Leniency\" is the opposite, and \"indecision\" and \"nostalgia\" do not describe disciplined editing." },
  { id: "t19rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author begins by conceding that early electric cars were slow and short-ranged, then argues that those very weaknesses pushed engineers to invent the batteries that now make the cars practical.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It recasts an early weakness as the source of a later strength.", "It denies that early electric cars had any flaws.", "It claims electric cars never improved.", "It lists car prices across decades."], correct: 0, explanation: "The early weaknesses are reframed as the spur for the batteries that made the cars practical (choice A). B and C contradict the concession and the improvement described, and D names content the passage lacks." },
  { id: "t19rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having rehearsed for weeks in a small studio ______ the vast concert hall felt intimidating to the young pianist.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the vast concert hall felt intimidating to the young pianist", "the young pianist found the vast concert hall intimidating", "intimidating was the vast concert hall", "it felt intimidating, the vast hall"], correct: 1, explanation: "The modifier \"Having rehearsed for weeks\" must describe the person who rehearsed, and only choice B places \"the young pianist\" right after it. The others illogically make \"the concert hall\" the one who rehearsed." },
  { id: "t19rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The compound killed the bacteria in a test tube. ______, it proved harmless to bacteria living inside infected tissue.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In living tissue, however", "For this reason", "Similarly"], correct: 1, explanation: "The contrast between test-tube success and failure inside tissue is best signaled by \"In living tissue, however.\" \"Consequently,\" \"For this reason,\" and \"Similarly\" all imply agreement rather than the reversal described." },
  { id: "t19rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic admired the symphony's ______ design, observing how a brief opening motif returns, reshaped, in every movement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["integrated", "fragmented", "arbitrary", "monotonous"], correct: 0, explanation: "A motif returning, reshaped, across every movement gives the work an \"integrated\" design. \"Fragmented\" and \"arbitrary\" suggest disorder, and \"monotonous\" implies dull sameness rather than purposeful unity." },
  { id: "t19rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across six schools, those that added a daily reading period saw test scores climb by an average of 12%, while those that kept their schedules unchanged saw no improvement.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding a daily reading period was associated with higher test scores.", "Keeping schedules unchanged raised scores.", "Reading periods had no relationship to scores.", "All six schools changed their schedules."], correct: 0, explanation: "Schools that added reading time saw a 12% rise while others saw none, supporting choice A. B and C contradict the data, and D contradicts the schools that kept schedules unchanged." },
  { id: "t19rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The architect's early sketches — rough, hurried, and barely legible ______ already revealed the bold curves of her later towers.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["sketches —", "sketches,", "sketches", "sketches;"], correct: 0, explanation: "A pair of dashes sets off the interrupting description, and the second dash must close it. A comma or semicolon cannot pair with the opening dash, and omitting punctuation leaves the interruption unclosed." },
  { id: "t19rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The board dismissed the analyst's forecast as ______, only to see the downturn she predicted arrive within the year.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["alarmist", "prescient", "accurate", "measured"], correct: 0, explanation: "Dismissing a forecast that then comes true means the board wrongly judged it \"alarmist\" (needlessly fearful). \"Prescient\" and \"accurate\" describe the forecast's correctness, which is the opposite of the board's dismissive view." },
  { id: "t19rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One historian blames the empire's collapse on overextended borders; another points to a collapse in tax revenue. A third contends that the two problems fed on each other.", prompt: "Which choice best describes the third historian's position?", type: "mcq", choices: ["The two proposed causes reinforced one another to bring on the collapse.", "Neither borders nor revenue mattered at all.", "Only overextended borders mattered.", "The empire never actually collapsed."], correct: 0, explanation: "The third historian says the two problems \"fed on each other,\" meaning they reinforced one another (choice A). B and D deny the causes or the collapse, and C names only one cause." },
  { id: "t19rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The engineers rebuilt the dam's spillway ______ the original had cracked under the record floodwaters.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["spillway, the", "spillway; the", "spillway the", "spillway: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone makes a splice, no punctuation makes a run-on, and a colon requires the second clause to explain or specify the first." },
  { id: "t19rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the boom's rewards were narrowly distributed. ______, downtown investors prospered while outlying neighborhoods saw little gain.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The second sentence gives a precise illustration of the narrow distribution, so \"Specifically\" fits. \"In contrast\" and \"Nevertheless\" signal opposition, and \"Otherwise\" implies an alternative outcome." },
  { id: "t19rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying up every loose thread, the screenwriter leaves the rivalry ______, inviting viewers to imagine how it might end.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "settled", "trivial", "concluded"], correct: 0, explanation: "Declining to tie up the threads leaves the rivalry \"unresolved.\" \"Settled\" and \"concluded\" mean the opposite, and \"trivial\" addresses importance rather than closure." },
  { id: "t19rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author acknowledges that her dataset covered only two seasons, but she argues that the pattern she observed was so pronounced and consistent that it warrants a multi-year study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["She admits a limitation while defending the importance of her finding.", "She claims her data are beyond question.", "She abandons her finding entirely.", "She argues no further study is needed."], correct: 0, explanation: "She concedes the short two-season window yet defends the finding's significance, exactly choice A. B overstates her confidence, and C and D contradict her call for a multi-year study." },
];

// ─────────────────────── PRACTICE TEST 19 · MATH M1 (22) ─────────────────────
const T19_M_M1: SatQuestion[] = [
  { id: "t19m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 8 = 43, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve for x. Subtract 8 from both sides to get 5x = 35, then divide by 5 to get x = 7. Check: 5(7) + 8 = 35 + 8 = 43. A common trap is dividing before subtracting the 8." },
  { id: "t19m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 2 cups of rice for every 6 servings. How many cups are needed for 15 servings?", type: "mcq", choices: ["5", "4", "6", "7"], correct: 0, explanation: "Goal: scale the ratio. Rice per serving is 2/6 = 1/3 cup. Multiply by 15 servings: (1/3)(15) = 5 cups. Check: 5 cups over 15 servings is 1/3 cup each, matching the recipe. The trap is multiplying 2 by 15 without dividing by 6." },
  { id: "t19m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² − 7, what is the value of f(2)?", type: "mcq", choices: ["5", "11", "1", "17"], correct: 0, explanation: "Goal: evaluate the function at x = 2. Substitute: f(2) = 3(2²) − 7 = 3(4) − 7 = 12 − 7 = 5. The trap is squaring after multiplying, giving (3·2)² = 36; order of operations requires squaring 2 first." },
  { id: "t19m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 16. What is its radius?", type: "grid", gridAnswers: ["8"], explanation: "Goal: find the radius. The radius is half the diameter, so r = 16/2 = 8. Check: doubling 8 gives the diameter of 16. The trap is doubling the diameter instead of halving it." },
  { id: "t19m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 5x − 3 passes through the point (2, k). What is the value of k?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find the y-value when x = 2. Substitute x = 2: k = 5(2) − 3 = 10 − 3 = 7. Check: the point (2, 7) satisfies the equation. The trap is subtracting before multiplying, giving 5(2 − 3) = −5." },
  { id: "t19m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: find the missing value. The mean equation is (6 + 10 + x)/3 = 9, so 16 + x = 27 and x = 11. Check: (6 + 10 + 11)/3 = 27/3 = 9. The trap is forgetting to multiply the mean by 3 to recover the total." },
  { id: "t19m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 5 = 26, what is the value of x?", type: "mcq", choices: ["7", "21", "9", "8"], correct: 0, explanation: "Goal: solve for x. Subtract 5 to get 3x = 21, then divide by 3 to get x = 7. Check: 3(7) + 5 = 21 + 5 = 26. The trap is forgetting to divide after subtracting, giving 21." },
  { id: "t19m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the sum of the roots. Factoring gives (x − 4)(x − 5) = 0, so the roots are 4 and 5 and their sum is 9. As a check, the sum of roots equals −b/a = 9/1 = 9. The trap is using the product (20) instead of the sum." },
  { id: "t19m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A book's price increased from $40 to $46. What was the percent increase?", type: "mcq", choices: ["15%", "6%", "12%", "20%"], correct: 0, explanation: "Goal: find percent increase. The increase is 46 − 40 = 6, and 6/40 = 0.15 = 15%. Check: 15% of 40 is 6, which added to 40 gives 46. The trap is using the new price 46 as the base instead of the original 40." },
  { id: "t19m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 45° and 65°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["70"], explanation: "Goal: find the third angle. The angles of a triangle sum to 180°, so the third is 180 − 45 − 65 = 70°. Check: 45 + 65 + 70 = 180. The trap is using 360° instead of 180° for a triangle." },
  { id: "t19m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A plumber charges a $40 service fee plus $30 per hour. Which equation gives the total cost C for h hours?", type: "mcq", choices: ["C = 30h + 40", "C = 40h + 30", "C = 70h", "C = 30h − 40"], correct: 0, explanation: "Goal: model the cost. The fixed fee $40 is added once and the $30 rate multiplies the hours h, giving C = 30h + 40. Check: at h = 0 the cost is the $40 fee, as expected. The trap is swapping the rate and the fixed fee." },
  { id: "t19m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 2) = x² + bx − 10, what is the value of b?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find b. Expanding the left side gives x² + 3x − 10, so matching the middle term shows b = 3. Check: the outer and inner products are −2x and 5x, which sum to 3x. The trap is adding 5 and −2 incorrectly or missing a sign." },
  { id: "t19m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 150 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["60", "40", "90", "75"], correct: 0, explanation: "Goal: find a part of a whole. Compute 40% of 150 as 0.40 × 150 = 60. Check: 60 out of 150 is indeed 40%. The trap is treating 40 as the count rather than a percentage." },
  { id: "t19m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 3) = 2x + 9, what is the value of x?", type: "mcq", choices: ["8", "6", "4", "12"], correct: 0, explanation: "Goal: solve for x. Distribute to get 5x − 15 = 2x + 9, subtract 2x to get 3x − 15 = 9, then 3x = 24 and x = 8. Check: 5(8 − 3) = 25 and 2(8) + 9 = 25. The trap is forgetting to distribute the 5 to the −3." },
  { id: "t19m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 12 and width 5. What is its perimeter?", type: "mcq", choices: ["34", "60", "17", "24"], correct: 0, explanation: "Goal: find the perimeter. Use P = 2(length + width) = 2(12 + 5) = 2(17) = 34. Check: the two lengths (24) plus the two widths (10) give 34. The trap is computing the area, 12 × 5 = 60, instead of the perimeter." },
  { id: "t19m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve the exponential equation. Write 27 as 3³, so 3^(x−1) = 3³ means x − 1 = 3 and x = 4. Check: 3^(4−1) = 3³ = 27. The trap is solving x − 1 = 27 or dividing 27 by 3." },
  { id: "t19m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "180", "90"], correct: 0, explanation: "Goal: convert map distance to real distance. Multiply 5 inches by 30 miles per inch: 5 × 30 = 150 miles. Check: 150 miles ÷ 30 miles per inch equals 5 inches. The trap is dividing instead of multiplying by the scale." },
  { id: "t19m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope. Use rise over run: (15 − 3)/(6 − 2) = 12/4 = 3. Check: going from x = 2 to x = 6 (run 4) the y rises by 12, which is 3 per unit. The trap is reversing the order of the coordinates in numerator and denominator." },
  { id: "t19m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 4x + 5, what value of x makes f(x) = 29?", type: "mcq", choices: ["6", "8", "7", "5"], correct: 0, explanation: "Goal: solve f(x) = 29. Set 4x + 5 = 29, subtract 5 to get 4x = 24, then x = 6. Check: 4(6) + 5 = 24 + 5 = 29. The trap is dividing 29 by 4 before subtracting the 5." },
  { id: "t19m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 7. What is its area, in terms of π?", type: "mcq", choices: ["49π", "14π", "7π", "21π"], correct: 0, explanation: "Goal: find the area. Use A = πr² = π(7²) = 49π. Check: squaring the radius 7 gives 49. The trap is using the circumference formula 2πr = 14π instead of the area formula." },
  { id: "t19m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4x − y = 17 and y = 3, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "3"], correct: 0, explanation: "Goal: solve for x. Substitute y = 3 to get 4x − 3 = 17, add 3 to get 4x = 20, then x = 5. Check: 4(5) − 3 = 20 − 3 = 17. The trap is subtracting 3 instead of adding it when moving it across." },
  { id: "t19m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 30-hour week?", type: "grid", gridAnswers: ["660"], explanation: "Goal: find total pay. Multiply the rate by the hours: 22 × 30 = 660 dollars. Check: 22 × 30 is the same as 22 × 3 × 10 = 66 × 10 = 660. The trap is adding the two numbers instead of multiplying." },
];

// ─────────────────────── PRACTICE TEST 19 · MATH M2 easy (22) ────────────────
const T19_M_M2E: SatQuestion[] = [
  { id: "t19m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 21, what is the value of x?", type: "grid", gridAnswers: ["12"], explanation: "Goal: solve for x. Subtract 9 from both sides to get x = 21 − 9 = 12. Check: 12 + 9 = 21. The trap is adding instead of subtracting." },
  { id: "t19m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 10% of 80?", type: "mcq", choices: ["8", "10", "18", "80"], correct: 0, explanation: "Goal: find a percentage. Compute 0.10 × 80 = 8. Check: 10% means one tenth, and one tenth of 80 is 8. The trap is shifting the decimal the wrong way to get 800." },
  { id: "t19m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 9 and a width of 4. What is its area?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the area. Multiply length by width: 9 × 4 = 36. Check: 9 × 4 is the same as 9 + 9 + 9 + 9 = 36. The trap is computing the perimeter, 2(9 + 4) = 26, instead." },
  { id: "t19m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 7x = 56, what is the value of x?", type: "mcq", choices: ["8", "7", "49", "63"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 7: x = 56 ÷ 7 = 8. Check: 7 × 8 = 56. The trap is subtracting 7 from 56 instead of dividing." },
  { id: "t19m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 5² − 4?", type: "grid", gridAnswers: ["21"], explanation: "Goal: evaluate the expression. First square: 5² = 25, then subtract: 25 − 4 = 21. Check: order of operations puts the exponent before the subtraction. The trap is doing 5² − 4 as (5 − 4)² = 1." },
  { id: "t19m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 8 of its 12 games. What fraction of its games did it win?", type: "mcq", choices: ["2/3", "8/12", "3/4", "1/8"], correct: 0, explanation: "Goal: write the fraction in simplest form. 8/12 reduces by dividing top and bottom by 4 to get 2/3. Check: 2/3 of 12 is 8. The trap is leaving the fraction unsimplified as 8/12." },
  { id: "t19m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 5 = 14, what is the value of x?", type: "grid", gridAnswers: ["19"], explanation: "Goal: solve for x. Add 5 to both sides: x = 14 + 5 = 19. Check: 19 − 5 = 14. The trap is subtracting 5 instead of adding it." },
  { id: "t19m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 12, 18, and 24?", type: "mcq", choices: ["18", "24", "16", "54"], correct: 0, explanation: "Goal: find the mean. Add the values: 12 + 18 + 24 = 54, then divide by 3 to get 18. Check: 18 sits exactly between 12 and 24 with 18 in the middle. The trap is forgetting to divide the sum by 3." },
  { id: "t19m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 6. What is its perimeter?", type: "grid", gridAnswers: ["24"], explanation: "Goal: find the perimeter. A square has four equal sides, so P = 4 × 6 = 24. Check: 6 + 6 + 6 + 6 = 24. The trap is squaring the side to get the area, 36, instead." },
  { id: "t19m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 3 = 15, what is the value of x?", type: "mcq", choices: ["6", "9", "7", "5"], correct: 0, explanation: "Goal: solve for x. Subtract 3 to get 2x = 12, then divide by 2 to get x = 6. Check: 2(6) + 3 = 12 + 3 = 15. The trap is dividing 15 by 2 before subtracting the 3." },
  { id: "t19m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 8, what is f(6)?", type: "grid", gridAnswers: ["14"], explanation: "Goal: evaluate the function. Substitute x = 6: f(6) = 6 + 8 = 14. Check: replacing x with 6 directly gives 14. The trap is multiplying instead of adding." },
  { id: "t19m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 5 notebooks for $10. How much do 8 notebooks cost?", type: "mcq", choices: ["$16", "$13", "$18", "$15"], correct: 0, explanation: "Goal: scale the unit price. Each notebook costs 10 ÷ 5 = $2, so 8 cost 8 × 2 = $16. Check: $16 ÷ 8 is $2 each, matching the rate. The trap is adding $3 to $10 because there are 3 more notebooks." },
  { id: "t19m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 48, what is the value of x?", type: "mcq", choices: ["8", "7", "6", "42"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 6: x = 48 ÷ 6 = 8. Check: 6 × 8 = 48. The trap is subtracting 6 from 48 instead of dividing." },
  { id: "t19m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 8 and a height of 5. What is its area?", type: "grid", gridAnswers: ["20"], explanation: "Goal: find the area of a triangle. Use A = (1/2)(base)(height) = (1/2)(8)(5) = 20. Check: half of 40 is 20. The trap is forgetting the factor of one-half and getting 40." },
  { id: "t19m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 25% of 60?", type: "mcq", choices: ["15", "25", "20", "30"], correct: 0, explanation: "Goal: find a percentage. 25% is one quarter, so 60 ÷ 4 = 15. Check: 15 × 4 = 60. The trap is taking half (30) instead of a quarter." },
  { id: "t19m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 7, what is the value of x?", type: "grid", gridAnswers: ["21"], explanation: "Goal: solve for x. Multiply both sides by 3: x = 7 × 3 = 21. Check: 21 ÷ 3 = 7. The trap is dividing by 3 instead of multiplying." },
  { id: "t19m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 3³?", type: "mcq", choices: ["27", "9", "6", "12"], correct: 0, explanation: "Goal: evaluate the power. 3³ means 3 × 3 × 3 = 27. Check: 3 × 3 = 9 and 9 × 3 = 27. The trap is multiplying 3 by 3 to get 9 or 3 by the exponent to get 9." },
  { id: "t19m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 120 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["40", "60", "360", "30"], correct: 0, explanation: "Goal: find average speed. Divide distance by time: 120 ÷ 3 = 40 mph. Check: 40 mph for 3 hours covers 120 miles. The trap is multiplying 120 by 3 instead of dividing." },
  { id: "t19m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x − 8 = 8, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve for x. Add 8 to get 4x = 16, then divide by 4 to get x = 4. Check: 4(4) − 8 = 16 − 8 = 8. The trap is dividing 8 by 4 before adding the 8 back." },
  { id: "t19m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a diameter of 18. What is its radius?", type: "mcq", choices: ["9", "18", "36", "27"], correct: 0, explanation: "Goal: find the radius. The radius is half the diameter, so 18 ÷ 2 = 9. Check: doubling 9 gives the diameter of 18. The trap is doubling the diameter instead of halving it." },
  { id: "t19m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x and x = 5, what is the value of y?", type: "mcq", choices: ["15", "8", "5", "3"], correct: 0, explanation: "Goal: evaluate y. Substitute x = 5: y = 3 × 5 = 15. Check: 15 ÷ 3 = 5, recovering x. The trap is adding 3 and 5 to get 8 instead of multiplying." },
  { id: "t19m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A jar holds 9 green and 6 yellow marbles. What fraction of the marbles are yellow?", type: "mcq", choices: ["2/5", "6/9", "1/2", "3/5"], correct: 0, explanation: "Goal: write the fraction of yellow marbles. There are 6 yellow out of 9 + 6 = 15 total, and 6/15 reduces to 2/5. Check: 2/5 of 15 is 6. The trap is writing 6/9 by comparing yellow only to green." },
];

// ─────────────────────── PRACTICE TEST 19 · MATH M2 hard (22) ────────────────
const T19_M_M2H: SatQuestion[] = [
  { id: "t19m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for the positive root. Add 64 to get x² = 64, so x = ±8, and the condition x > 0 selects x = 8. Check: 8² − 64 = 64 − 64 = 0. The trap is taking the negative root or dividing 64 by 2." },
  { id: "t19m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 3y = 22 and x − 3y = 3, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "3"], correct: 0, explanation: "Goal: solve the system for x. Adding the two equations eliminates y: (4x + 3y) + (x − 3y) = 22 + 3 gives 5x = 25, so x = 5. Check: with x = 5, the second equation gives 5 − 3y = 3, so y = 2/3, and 4(5) + 3(2/3) = 20 + 2 = 22. The trap is subtracting the equations instead of adding." },
  { id: "t19m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^x = 64, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve the exponential. Write 64 as a power of 2: 64 = 2⁶, so x = 6. Check: 2⁶ = 64. The trap is dividing 64 by 2 to get 32 instead of finding the exponent." },
  { id: "t19m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $90 is marked up by 30%. What is the new price?", type: "mcq", choices: ["$117", "$120", "$110", "$63"], correct: 0, explanation: "Goal: apply a markup. 30% of 90 is 0.30 × 90 = 27, and 90 + 27 = $117. Equivalently, 1.30 × 90 = 117. Check: $117 is 30% above $90. The trap is subtracting the markup instead of adding it." },
  { id: "t19m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 8 and 15. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["17"], explanation: "Goal: find the hypotenuse. By the Pythagorean theorem, c = √(8² + 15²) = √(64 + 225) = √289 = 17. Check: 8-15-17 is a known right-triangle triple. The trap is adding the legs (23) instead of using their squares." },
  { id: "t19m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(4))?", type: "mcq", choices: ["28", "10", "34", "22"], correct: 0, explanation: "Goal: compose the function. First p(4) = 3(4) − 2 = 10, then p(10) = 3(10) − 2 = 28. Check: substituting twice in order gives 28. The trap is computing p(4) and stopping at 10 instead of applying p again." },
  { id: "t19m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 5y = 19 and x = y + 1, what is the value of y?", type: "grid", gridAnswers: ["17/7", "2.428", "2.43"], explanation: "Goal: solve the system for y. Substitute x = y + 1: 2(y + 1) + 5y = 19 gives 7y + 2 = 19, so 7y = 17 and y = 17/7 ≈ 2.43. Check: x = 17/7 + 1 = 24/7, and 2(24/7) + 5(17/7) = 48/7 + 85/7 = 133/7 = 19. The trap is dropping the parentheses and forgetting to distribute the 2." },
  { id: "t19m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 12 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the x-coordinate of the vertex. Use h = −b/(2a) = −(−8)/(2·1) = 8/2 = 4. Check: the axis of symmetry x = 4 lies midway between the roots 2 and 6. The trap is forgetting the negative sign and getting −4." },
  { id: "t19m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the acute angle θ has cos θ = 8/17. What is sin θ?", type: "mcq", choices: ["15/17", "8/15", "17/15", "15/8"], correct: 0, explanation: "Goal: find sin θ from cos θ. With adjacent 8 and hypotenuse 17, the opposite side is √(17² − 8²) = √(289 − 64) = √225 = 15, so sin θ = 15/17. Check: (8/17)² + (15/17)² = (64 + 225)/289 = 1. The trap is using 8/15 instead of the opposite over the hypotenuse." },
  { id: "t19m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["10"], explanation: "Goal: find b. A perfect square (x + a)² = x² + 2ax + a² needs a² = 25, so a = 5 and b = 2a = 10. Check: (x + 5)² = x² + 10x + 25. The trap is setting b equal to 5 (the value of a) rather than 2a." },
  { id: "t19m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−1", "5", "8"], correct: 0, explanation: "Goal: find the y-intercept b. Using y = −3x + b with the point (2, 5): 5 = −3(2) + b, so 5 = −6 + b and b = 11. Check: the line y = −3x + 11 passes through (2, 5). The trap is sign error, adding −6 incorrectly to get −1." },
  { id: "t19m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a tablet costs $360. What was the original price?", type: "mcq", choices: ["$480", "$450", "$420", "$385"], correct: 0, explanation: "Goal: reverse a discount. Paying 75% of the original gives 0.75 × original = 360, so original = 360 ÷ 0.75 = $480. Check: 25% of 480 is 120, and 480 − 120 = 360. The trap is adding 25% of 360 back, which uses the wrong base." },
  { id: "t19m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 49 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-7"], explanation: "Goal: find the negative root. Since a² = 49, a = ±7, and the condition a < 0 selects a = −7. Check: (−7)² = 49. The trap is reporting the positive root 7 and ignoring the a < 0 condition." },
  { id: "t19m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: find the volume. Use V = πr²h = π(4²)(6) = π(16)(6) = 96π. Check: 16 × 6 = 96. The trap is using r instead of r², which would give 24π." },
  { id: "t19m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["4/3", "1.333", "1.33"], explanation: "Goal: solve for x. Subtract 1/4: 1/x = 1 − 1/4 = 3/4, so x = 4/3 ≈ 1.33. Check: 1/(4/3) + 1/4 = 3/4 + 1/4 = 1. The trap is taking the reciprocal incorrectly and writing 3/4 as the answer." },
  { id: "t19m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "3"], correct: 0, explanation: "Goal: find the product of the roots. Factoring gives (x − 2)(x − 5) = 0, so the roots are 2 and 5 and their product is 10. As a check, the product equals c/a = 10/1 = 10. The trap is using the sum (7) instead of the product." },
  { id: "t19m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of pencils to pens in a box is 2:7. If there are 45 items total, how many are pens?", type: "mcq", choices: ["35", "30", "14", "28"], correct: 0, explanation: "Goal: split a total by a ratio. The parts total 2 + 7 = 9, so each part is 45 ÷ 9 = 5, and pens are 7 × 5 = 35. Check: pencils are 2 × 5 = 10, and 10 + 35 = 45. The trap is taking 7/9 of 45 incorrectly or using the pencil count." },
  { id: "t19m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 5, what is the area of the larger?", type: "grid", gridAnswers: ["80"], explanation: "Goal: scale the area. Areas of similar figures scale by the square of the linear ratio, so the larger area is 5 × 4² = 5 × 16 = 80. Check: the area ratio is 1:16, and 5 × 16 = 80. The trap is multiplying by 4 instead of 4²." },
  { id: "t19m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "grid", gridAnswers: ["31"], explanation: "Goal: solve the radical equation. Square both sides: x + 5 = 36, so x = 31. Check: √(31 + 5) = √36 = 6. The trap is forgetting to square the 6, leaving x + 5 = 6." },
  { id: "t19m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 2y = 24 and y = 3, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "7"], correct: 0, explanation: "Goal: solve for x. Substitute y = 3: 5x − 6 = 24, add 6 to get 5x = 30, then x = 6. Check: 5(6) − 2(3) = 30 − 6 = 24. The trap is subtracting 6 from 24 instead of adding it back." },
  { id: "t19m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the root. The expression factors as (x − 3)², which equals 0 only when x = 3. Check: 3² − 6(3) + 9 = 9 − 18 + 9 = 0. The trap is expecting two distinct roots when this perfect square has just one." },
  { id: "t19m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of bacteria triples every hour. If it starts at 20, how many are there after 3 hours?", type: "mcq", choices: ["540", "180", "60", "120"], correct: 0, explanation: "Goal: apply exponential growth. After 3 hours the count is 20 × 3³ = 20 × 27 = 540. Check: 20 → 60 → 180 → 540 over three triplings. The trap is multiplying by 3 only once (60) instead of cubing the factor." },
];

